#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to;
    int time;
    int cost;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int V, N, M;
    if (!(cin >> V >> N >> M)) return 0;

    vector<vector<Edge>> adj(N + 1);

    for (int i = 0; i < M; ++i) {
        int A, B, T, P;
        cin >> A >> B >> T >> P;
        adj[A].push_back({B, T, P});
        adj[B].push_back({A, T, P});
    }

    int X, Y;
    cin >> X >> Y;

    const long long INF = (1LL << 60);
    int W = N + 1;

    vector<long long> dist((V + 1) * W, INF);
    auto id = [&](int cost, int node) {
        return cost * W + node;
    };

    priority_queue<
        tuple<long long, int, int>,
        vector<tuple<long long, int, int>>,
        greater<tuple<long long, int, int>>
    > pq;

    dist[id(0, X)] = 0;
    pq.emplace(0, X, 0);

    long long answer = -1;

    while (!pq.empty()) {
        auto [currentTime, u, currentCost] = pq.top();
        pq.pop();

        if (currentTime != dist[id(currentCost, u)]) continue;

        if (u == Y) {
            answer = currentTime;
            break;
        }

        for (const Edge &e : adj[u]) {
            int newCost = currentCost + e.cost;
            if (newCost > V) continue;

            long long newTime = currentTime + e.time;
            int idx = id(newCost, e.to);

            if (newTime < dist[idx]) {
                dist[idx] = newTime;
                pq.emplace(newTime, e.to, newCost);
            }
        }
    }

    cout << answer << '\n';
    return 0;
}
